package kr.yunseok.touchmacro;
import org.junit.Test;
import java.lang.reflect.*;
import static org.junit.Assert.*;
public class AiStartGateTest {
    private Class<?> type(){try{return Class.forName("kr.yunseok.touchmacro.AiStartGate");}catch(ClassNotFoundException error){fail("AI 첫 입력의 실제 대상 창 허가가 없습니다");return null;}}
    private Object invoke(Object gate,String name,Class<?>[] types,Object... arguments)throws Exception{try{return gate.getClass().getMethod(name,types).invoke(gate,arguments);}catch(InvocationTargetException error){throw (Exception)error.getCause();}}
    private Object macro(Macro macro,String target)throws Exception{try{return type().getMethod("macro",Macro.class,String.class,String.class).invoke(null,macro,target,"kr.yunseok.touchmacro");}catch(InvocationTargetException error){throw (Exception)error.getCause();}}
    private boolean observe(Object gate,String pkg,boolean paused)throws Exception{return (Boolean)invoke(gate,"observe",new Class<?>[]{String.class,boolean.class},pkg,paused);}
    @Test public void ownUiUnknownAndSystemTransitionsCannotAuthorizeFirstInput()throws Exception{Object gate=macro(AiCompilerTest.neutral(),"com.example.target");assertFalse(observe(gate,"kr.yunseok.touchmacro",false));assertFalse(observe(gate,"",false));assertFalse((Boolean)invoke(gate,"open",new Class<?>[]{}));assertTrue(observe(gate,"com.example.target",false));}
    @Test public void unrelatedExternalAppAndMissingTargetAreRejected()throws Exception{try{macro(AiCompilerTest.neutral(),"");fail();}catch(IllegalArgumentException expected){}Object gate=macro(AiCompilerTest.neutral(),"com.example.target");try{observe(gate,"com.example.other",false);fail();}catch(IllegalArgumentException expected){}assertFalse((Boolean)invoke(gate,"open",new Class<?>[]{}));}
    @Test public void actualStartAtAndDisabledSkipDetermineFirstAppOnce()throws Exception{Macro m=AiCompilerTest.neutral();Step skipped=new Step("APP");skipped.packageName="com.example.wrong";skipped.enabled=false;m.steps.add(skipped);Step app=new Step("APP");app.packageName="com.example.actual";app.repeat=2;app.after=850;m.steps.add(app);m.startAt=2;Object gate=macro(m,"");assertEquals("com.example.actual",invoke(gate,"target",new Class<?>[]{}));assertTrue((Boolean)invoke(gate,"engineAppFirst",new Class<?>[]{}));assertTrue((Boolean)invoke(gate,"permitsInitialApp",new Class<?>[]{Step.class},app));invoke(gate,"appLaunched",new Class<?>[]{Step.class},app);assertFalse((Boolean)invoke(gate,"permitsInitialApp",new Class<?>[]{Step.class},app));assertTrue(observe(gate,"com.example.actual",false));assertEquals(2,app.repeat);assertEquals(850,app.after);assertEquals(2,m.startAt);}
    @Test public void leadingGotoDoesNotPredictItsFutureAppAndWatchNeverUsesMacroPrelude()throws Exception{Macro m=AiCompilerTest.neutral();m.steps.get(0).type="GOTO";m.steps.get(0).target=2;Step app=new Step("APP");app.packageName="com.example.body";m.steps.add(app);try{macro(m,"");fail();}catch(IllegalArgumentException expected){}WatchConfig watch=new WatchConfig();watch.targetPackage="com.example.list";Object gate=type().getMethod("watch",WatchConfig.class,String.class,String.class).invoke(null,watch,"com.example.list","kr.yunseok.touchmacro");assertEquals("com.example.list",invoke(gate,"target",new Class<?>[]{}));assertFalse((Boolean)invoke(gate,"engineAppFirst",new Class<?>[]{}));assertFalse((Boolean)invoke(gate,"permitsInitialApp",new Class<?>[]{Step.class},app));}
    @Test public void committedGateSuspendsDuringPauseAndFreshObservationCanResume()throws Exception{Object gate=macro(AiCompilerTest.neutral(),"com.example.target");assertFalse(observe(gate,"com.example.target",true));assertFalse((Boolean)invoke(gate,"open",new Class<?>[]{}));assertTrue(observe(gate,"com.example.target",false));}
}
